public int processOrders(List<Order> orders) {
    int processedCount = 0;
    int notifiedCount = 0;
    for (Order order : orders) {
        switch (order.getStatus()) {
            case CANCELLED:
                order.archive();
                break;
            case PENDING:
                order.markProcessing();
                processedCount++;
                break;
            case COMPLETED:
                processedCount++;
                break;
        }
        notifiedCount++;
        order.notifyStatusChange();
    }
    return processedCount;
}
